INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16245, '公式：附魔靴子 - 强效敏捷', '教你学会永久性地为一双靴子附魔，使其获得敏捷+7的效果。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16246, '公式：附魔护腕 - 超强力量', '教你学会永久性地为一副护腕附魔，使其获得力量+9的效果。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16247, '公式：附魔武器 - 超强冲击', '教你学会永久性地为一把双手近战武器附魔，使其获得伤害+9的效果。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16248, '公式：附魔武器 - 邪恶', '教你学会永久性地为一件近战武器附魔，使其有时可以诅咒目标，对其造成暗影伤害并降低它们的近战伤害。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16249, '公式：附魔双手武器 - 特效智力', '教你学会永久性地为一把双手近战武器附魔，使其获得智力+9的效果。');
