INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16251, '公式：附魔护腕 - 超强耐力', '教你学会永久性地为一副护腕附魔，使其获得耐力+9的效果。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16252, '公式：附魔武器 - 十字军', '教你学会永久性地为一把近战武器附魔，使其在近战攻击命中目标时经常获得神圣之力，为装备者恢复75到125点生命值，并使其力量提高100点，持续15秒。对60级以上玩家的效果降低。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16253, '公式：附魔胸甲 - 强效属性', '教你学会永久性地为一件胸甲附魔，使其获得所有属性提高4点的效果。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (16254, '公式：附魔武器 - 生命偷取', '教你学会永久性地为一件近战武器附魔，使其有时可偷取对手的生命值并将其转移给装备者。对60级以上玩家的效果降低。');
