INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43627, '萨尔的金币', '格罗姆，我的老朋友，愿你安息。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43628, '吉安娜·普罗德摩尔的金币', '阿尔萨斯，我的挚爱，请回到我身边来。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43629, '乌瑟尔·光明使者的金币', '年轻的阿尔萨斯必须学会以耐心控制自己的力量。我祈祷他能了解到领袖的真谛在于品德，而非蛮力。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43630, '提里奥·弗丁的金币', '我希望泰兰能够茁壮成长，保卫他所关心的人。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43631, '塔隆的金币', '许愿是蠢货的消遣。这枚金币就当是挖掉你眼睛的报酬吧。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43632, '希尔瓦娜斯·风行者的金币', '希望姐妹们和我一起长大，一起出嫁。这枚金币似乎很古老了。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43633, '凯尔萨斯王子的金币', '那个名叫吉安娜的年轻学徒，就一名人类女子来说，已经算是很有吸引力了。我希望她能认识到我的优雅和强大。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43634, '卡特拉娜·普瑞斯托的金币', '听着，小小的许愿泉。把你全部的力量都交给我，不然有你好看。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43635, '克尔苏加德的金币', '有时候……我真希望有人能给我一个热情而温暖的拥抱。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43636, '克罗米的金币', '真希望跟我打招呼的那些家伙不再讲有关侏儒或者时间旅行的冷笑话。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43637, '布莱恩·铜须的金币', '布莱恩·铜须到此一游。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43638, '阿鲁高的金币', '我希望有一天可以退休回到自己的小别墅中颐养天年，养几只小狗当宠物。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43639, '阿尔萨斯的金币', '我已经是一个王国的储君了，将要治理大片的疆土。还能许什么愿呢？不如来一个凉快点的座位……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43640, '阿克蒙德的金币', '我想知道你要如何在我的怒火中幸存下来，小喷泉。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43641, '安度因·乌瑞恩的金币', '我希望自己能快快长大。好像我一直都是10岁的样子。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43643, '麦格尼·铜须王子的银币', '我希望父亲和兄弟们比我更健康长寿。我自己当不当国王无所谓。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43644, '农夫的银币', '我真健忘！真希望自己的记忆力更好一点。等等，我是不是已经扔了一枚硬币进去？');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43645, '扭曲的鱼钩', '好像有人想在喷泉里钓鱼。谁会傻到这种地步？');
