INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43676, '奥术师杜安的银币', '啊，你为什么不在乎我？阿比迪斯，我愿意跟随你到天涯海角。希望你能在乎我一点……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43677, '大工匠梅卡托克的银币', '这喷泉的工作原理是什么？我想自己也造一座出来。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43678, '安东尼达斯的银币', '给我力量接受那些我无法改变的事情，给我勇气改变那些我可以改变的事情，给我智慧看清这两者之间的差别。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43679, '穆拉丁·铜须的银币', '愿圣光保佑我们这支诺森德远征队。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43680, '瓦里安·乌瑞恩国王的银币', '希望家乡的那场暴动马上平息。我不想看到任何人受伤害。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43681, '泰瑞纳斯·米奈希尔国王的银币', '希望我的儿子阿尔萨斯能为他的子民鞠躬尽瘁。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43682, '安纳斯特里亚·逐日者国王的银币', '希望小凯尔萨斯能明白，总有一天，他要肩负起领导所有子民的重任。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43683, '卡德加的银币', '图拉扬和奥蕾莉亚，无论你们在哪里，希望你们安然无恙。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43684, '麦迪文的银币', '<你感觉到脑袋里有三个声音在说话，其中两个声音很嘈杂，第三个隐约可以分辨出内容。>');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43685, '玛维·影歌的银币', '伊利丹去哪了？');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43686, '奥蕾莉亚的银币', '希望我的妹妹们可以了解自己的潜能，以她们的事迹为风行者家族争光。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43687, '艾格文的银币', '我真的希望你们这些法师少啃几本书，多用用脑子。');
