INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43698, '巨型下水道老鼠', '教你学会召唤这种小伙伴。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43699, '血肉诅咒圆盘', '这东西上面记载着信息？真的？明明一个字都没有啊！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43701, '某位步兵的铜币', '真希望我跟那个整天扛着木材闲逛的表哥换一下……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43702, '阿隆索斯·法奥的铜币', '我希望能向芸芸众生宣讲圣光之道，教他们学会理解三大美德的价值。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43703, '安斯雷姆的铜币', '我希望女儿天天快乐，并且可以接受我。她在这里感觉很拘束……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43704, '阿图门的铜币', '我能许愿一个更加舒适的马鞍吗？我的屁股很疼。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43705, '达纳斯·托尔贝恩的铜币', '我希望有一个巨魔死掉……现在就死。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43706, '多尔南的亮晶晶的铜币', '我希望阿尔萨斯那个坏蛋掉进一堆猛犸人的便便里！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43707, '伊崔格的铜币', '希望提里奥的诺森德之旅以胜利告终，或者，希望他光荣地战死在沙场上。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43708, '埃林·提亚斯的铜币', '盗贼这个行业可真不轻松。我希望能为了真正的理想而奋斗……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43709, '弗斯塔德·蛮锤的铜币', '希望我的故事也能被写进书中。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43710, '吉恩的铜币', '哈！吉尔尼斯的喷泉可以实现的愿望比达拉然的喷泉多十倍！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43711, '英尼戈的铜币', '希望父亲能回到我身边……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43712, '克拉苏斯的铜币', '我为了那些仍在格瑞姆巴托受苦的兄弟姐妹而祈祷。我一定要解救他们。一定。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43713, '克里尔的铜币', '爆炸。现在就爆炸。我希望能看到爆炸。快爆炸！这硬币肯定是有问题，不知道它到底能不能爆炸。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43714, '兰德鲁·郎绍特的铜币', '希望我能拿回这枚铜币……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43715, '穆罗克的铜币', '只要一次就行了——真的，一次就行——让那个姑娘和我一起骑狮鹫去兜风。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43716, '奔波尔霸的铜币', '希望诺森德的水变暖和一点，冻得我都快睡着啦！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43717, '佳莉娅·米奈希尔公主的铜币', '我希望那个英俊的贵族，普瑞斯托大人，能够注意到我！他真是太帅了！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43718, '列兵马库斯·乔纳森的铜币', '我希望能长出漂亮而浓密的胡须。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43719, '萨兰蒂亚的亮晶晶的铜币', '总有一天，我要比这些法师都更厉害！');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43720, '侍卫洛文的铜币', '我希望能调离暴风城，并且再次见到瑟尔希。这座城市一点都不好。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43721, '斯塔文的铜币', '你们这些法师居然拒绝帮助两个相爱的人走到一起，只因为其中一个还没有发现他们是天造地设的一对？我希望你们全部完蛋。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43722, '温蕾萨的铜币', 'Asto\'re da shan\'re。Turus Fulo Il\'amare，A\'Talah Adore。Isera\'duna……');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43723, '瓦格斯的铜币', '希望杉德尔船长快点把我的酒运过来。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (43724, '天界红宝石戒指', '戒指？这东西更像是一条项链，而且还是很重的那种！');
