INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (50735, '缚誓者，游侠将军的战刃', '顶部铸有一颗狞笑的颅骨，刃锋上层层叠叠地刻着几个血字：痛不欲生。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (50736, '天堂陨落，大谎言之刃', '谎言伤人，媚语坏事。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (50737, '浩劫的召唤，洛丹伦王权之斧', '让敌人知道，他们的末日将在浩劫的召唤声中降临。');
INSERT INTO `locales_item` (`entry`, `name_loc4`, `description_loc4`) VALUES (50738, '米瑟里奥斯，铜须的遗产', '一行被天灾腐蚀的铭文依稀可辨：随我高喊，让声音在冰封王座旁回响——为了联盟，为了卡兹莫丹！');
